  /* v28.xx (cw-uishared-title), his order 2026-10-18 (UI step 2, one shared look): the style guide as tokens. FIVE type sizes, an 8px
     space grid, one radius, one scrim, the button heights. UIT in the script is the same table; the check keeps them equal. */
  --fs-hero:56px; --fs-title:32px; --fs-body:20px; --fs-label:16px; --fs-fine:14px;
  --sp-1:8px; --sp-2:16px; --sp-3:24px; --sp-4:32px; --sp-5:48px; --rad:4px; --scrim:rgba(6,7,8,.80); --track:.04em;
  --btn-h:56px; --btn-h-sm:48px; --btn-h-xs:40px; --menu-w:560px; --acc-hover:#f7c25a; --acc-press:#dfa52f;
}

  special:UIC.r_elite, plate:'rgba(6,9,13,.78)', dangerPlate:'rgba(40,8,6,.84)', ink:INK};
// v28.xx (cw-uishared-title), his order 2026-10-18 (UI step 2, one shared look): UIT is the style guide as ONE table (the same numbers as
// the :root tokens --fs-*, --sp-*, --rad; the check keeps them equal). uiFont(role,z) is the type of a role at a screen scale z, uiPanel
// is Panel P on a canvas (fill --ui-panel at 90 percent, a 1px --ui-line-hi border, --rad, an optional 3px accent bar). The DOM side is
// the CSS block <style id="ui-shared">; the HUD side keeps hudPlate/hudText, whose colours already come from UIC.
var UIT={fs:{hero:56,title:32,body:20,label:16,fine:14}, sp:{1:8,2:16,3:24,4:32,5:48}, rad:4, scrim:0.8, track:0.04, btn:{h:56,hs:48,hx:40}};
function uiFont(role,z){
  var r=UIT.fs[role]?role:'body', w={hero:800,title:700,body:600,label:600,fine:500}[r];
  return w+' '+Math.round(UIT.fs[r]*((z>0)?z:1)*100)/100+'px '+((r==='fine')?HUDFB:HUDF);
}
function uiPanel(c,x,y,w,h,accent){
  if(!(w>0&&h>0)) return;
  var r=Math.max(0,Math.min(UIT.rad,h/2,w/2));
  c.save();
  c.beginPath();
  if(c.roundRect) c.roundRect(x+0.5,y+0.5,w-1,h-1,r);
  else { c.moveTo(x+r,y); c.arcTo(x+w,y,x+w,y+h,r); c.arcTo(x+w,y+h,x,y+h,r); c.arcTo(x,y+h,x,y,r); c.arcTo(x,y,x+w,y,r); c.closePath(); }
  c.globalAlpha=0.9; c.fillStyle=UIC.ui_panel; c.fill();
  c.globalAlpha=1; c.lineWidth=1; c.strokeStyle=UIC.ui_line_hi; c.stroke();
  if(accent){ c.fillStyle=accent; c.fillRect(x,y+r,3,h-r*2); }
  c.restore();
}

check:
{v:'VER',what:'the title and mode menu run on the shared look: tokens in the CSS equal UIT, the ui-shared block has no raw color or font-size literals, the mode rows are 20px with a 4px radius, Panel P draws (his order 2026-10-18, one shared UI)',
 run:function(){
   if(typeof UIT==='undefined'||typeof uiFont!=='function'||typeof uiPanel!=='function') return 'no shared UI object (UIT, uiFont, uiPanel)';
   var st=document.getElementById('ui-shared'), cs=getComputedStyle(document.documentElement), k, txt, bodies, i, bad=[], cv, c, d, e;
   if(!st) return 'no <style id=ui-shared> block';
   for(k in UIT.fs){ if(cs.getPropertyValue('--fs-'+k).trim()!==UIT.fs[k]+'px') return 'token --fs-'+k+' is not UIT.fs.'+k; }
   for(k in UIT.sp){ if(cs.getPropertyValue('--sp-'+k).trim()!==UIT.sp[k]+'px') return 'token --sp-'+k+' is not UIT.sp.'+k; }
   if(cs.getPropertyValue('--rad').trim()!==UIT.rad+'px') return 'token --rad is not UIT.rad';
   txt=st.textContent.replace(/\/\*[\s\S]*?\*\//g,'');
   bodies=txt.match(/\{[^}]*\}/g)||[];
   for(i=0;i<bodies.length;i++){
     if(/#[0-9a-fA-F]{3,8}\b/.test(bodies[i])||/rgba?\(/.test(bodies[i])||/font-size\s*:\s*[\d.]+(px|em|rem)/.test(bodies[i])||/font\s*:[^;]*[\d.]+px/.test(bodies[i])||/(^|[^\w.-])(?!1px\b|3px\b)\d+(\.\d+)?px/.test(bodies[i])) bad.push(bodies[i].slice(0,70));
   }
   if(bad.length) return 'ui-shared still has raw literals: '+bad[0];
   if(!bodies.length||txt.indexOf('#title')<0) return 'ui-shared has no title rules';
   e=document.getElementById('modecoop'); if(!e) return 'no mode row';
   if(getComputedStyle(e).fontSize!=='20px') return 'mode row font is '+getComputedStyle(e).fontSize+', not the 20px body size';
   if(getComputedStyle(e).borderTopLeftRadius!=='4px') return 'mode row radius is '+getComputedStyle(e).borderTopLeftRadius+', not 4px';
   if(getComputedStyle(document.getElementById('titlestart')).minHeight!=='56px') return 'the 1 player button is not the 56px primary';
   if(uiFont('title',2).indexOf('64px')<0) return 'uiFont(title,2) is '+uiFont('title',2);
   cv=document.createElement('canvas'); cv.width=40; cv.height=30; c=cv.getContext('2d');
   uiPanel(c,0,0,40,30,null);
   d=c.getImageData(20,15,1,1).data;
   if(Math.abs(d[0]-22)>2||Math.abs(d[1]-25)>2||Math.abs(d[2]-27)>2||Math.abs(d[3]-230)>3) return 'uiPanel fill is '+d[0]+','+d[1]+','+d[2]+','+d[3]+', not panel at 90 percent';
   d=c.getImageData(20,0,1,1).data;
   if(d[3]<200||d[0]<60) return 'uiPanel has no 1px border';
   return null;
 }},
